<?php
namespace App\Services\Ledger;
use App\Models\GlBatch; use App\Services\Audit\ActivityLogService; use DomainException; use Illuminate\Support\Facades\DB;
class GeneralLedgerService { public function __construct(private ActivityLogService $audit){} public function postBatch(array $header,array $lines): GlBatch { if(count($lines)<2)throw new DomainException('GL batch requires at least two lines.');$debit=0.0;$credit=0.0;foreach($lines as $line){$d=(float)($line['debit']??0);$c=(float)($line['credit']??0);if($d<0||$c<0||($d<=0&&$c<=0)||($d>0&&$c>0))throw new DomainException('Each GL line must contain exactly one positive side.');$debit+=$d;$credit+=$c;}if(abs($debit-$credit)>0.0001)throw new DomainException('GL batch is not balanced.');return DB::transaction(function() use($header,$lines){$batch=GlBatch::create(array_merge($header,['status'=>'POSTED']));foreach($lines as $line)$batch->entries()->create(array_merge($line,['status'=>'POSTED']));$batch->load('entries');$this->audit->record('ledger.gl','post',$batch,[],$batch->toArray(),['document_number'=>$batch->document_number]);return $batch;});} }
